      mr: "ॐ पृथिव्याः (पृथिवीमन्त्रस्य) मेरुपृष्ठ ऋषिः । कूर्मो देवता । सुतलं छन्दः । आसने विनियोगः ॥\nअनन्तासनाय नमः ॥\nॐ पृथ्वि! त्वया धृता लोका देवि! त्वं विष्णुना धृता ।\nत्वं च धारय मां देवि! पवित्रं कुरु चासनम् ॥",

      kn: "ಓಂ ಪೃಥಿವ್ಯಾಃ (ಪೃಥಿವೀಮಂತ್ರಸ್ಯ) ಮೇರುಪೃಷ್ಠ ಋಷಿಃ । ಕೂರ್ಮೋ ದೇವತಾ । ಸುತಲಂ ಛಂದಃ । ಆಸನೇ ವಿನಿಯೋಗಃ ॥\nಅನಂತಾಸನಾಯ ನಮಃ ॥\nಓಂ ಪೃಥ್ವಿ! ತ್ವಯಾ ಧೃತಾ ಲೋಕಾ ದೇವಿ! ತ್ವಂ ವಿಷ್ಣುನಾ ಧೃತಾ ।\nತ್ವಂ ಚ ಧಾರಯ ಮಾಂ ದೇವಿ! ಪವಿತ್ರಂ ಕುರು ಚಾಸನಮ್ ॥"
