      mr: "शुभाभ्युदयार्थं च शुभे शोभने मङ्गलेमुहूर्ते अत्र पृथिव्यां जम्बूद्वीपे भरतवर्षे भरतखण्डे मेरोः दक्षिणदिग्भागे श्रीशैलस्य वायव्य [आग्नेय] प्रदेशे, श्रीकृष्णा गोदावर्योर्मध्यदेशे [श्री कृष्णाकावेर्योर्मध्य देशे] लक्ष्मी निवासगृहे, समस्तदेवता ब्राह्मण हरिहर सन्निधौ । अद्यब्रह्मणः द्वितीय परार्धे, श्वेतवराहकल्पे, वैवस्वत मन्वन्तरे, कलियुगे, प्रथमपादे, अस्मिन् वर्तमान व्यावहारिक चान्द्रमानेन ------ नाम संवत्सरे ----- अयने ------ ऋतौ --- मासे ----- पक्षे ----- तिथौ ----- वासरे, शुभवासरे, शुभनक्षत्रे, शुभयोगे, शुभकरण, एवं गुण विशेषण विशिष्टायां शुभतिथौ मम उपात्तदुरितक्षय द्वारा श्रीपरमेश्वरमुद्दिश्य, श्रीपरमेश्वर प्रीत्यर्थं प्रातः सन्ध्यामुपासिष्ये ॥",
      kn: "ಶುಭಾಭ್ಯುದಯಾರ್ಥಂ ಚ ಶುಭೇ ಶೋಭನೇ ಮಂಗಳೇಮುಹೂರ್ತೇ ಅತ್ರ ಪೃಥಿವ್ಯಾಂ ಜಂಬೂದ್ವೀಪೇ ಭರತವರ್ಷೇ ಭರತಖಂಡೇ ಮೇರೋಃ ದಕ್ಷಿಣದಿಗ್ಭಾಗೇ ಶ್ರೀಶೈಲಸ್ಯ ವಾಯವ್ಯ [ಆಗ್ನೇಯ] ಪ್ರದೇಶೇ, ಶ್ರೀಕೃಷ್ಣಾ ಗೋದಾವರ್ಯೋರ್ಮಧ್ಯದೇಶೇ [ಶ್ರೀ ಕೃಷ್ಣಾಕಾವೇರ್ಯೋರ್ಮಧ್ಯ ದೇಶೇ] ಲಕ್ಷ್ಮೀ ನಿವಾಸಗೃಹೇ, ಸಮಸ್ತದೇವತಾ ಬ್ರಾಹ್ಮಣ ಹರಿಹರ ಸನ್ನಿಧೌ । ಅದ್ಯಬ್ರಹ್ಮಣಃ ದ್ವಿತೀಯ ಪರಾರ್ಧೇ, ಶ್ವೇತವರಾಹಕಲ್ಪೇ, ವೈವಸ್ವತ ಮನ್ವಂತರೇ, ಕಲಿಯುಗೇ, ಪ್ರಥಮಪಾದೇ, ಅಸ್ಮಿನ್ ವರ್ತಮಾನ ವ್ಯಾವಹಾರಿಕ ಚಾಂದ್ರಮಾನೇನ ------ ನಾಮ ಸಂವತ್ಸರೇ ----- ಅಯನೇ ------ ಋತೌ --- ಮಾಸೇ ----- ಪಕ್ಷೇ ----- ತಿಥೌ ----- ವಾಸರೇ, ಶುಭವಾಸರೇ, ಶುಭನಕ್ಷತ್ರೇ, ಶುಭಯೋಗೇ, ಶುಭಕರಣ, ಏವಂ ಗುಣ ವಿಶೇಷಣ ವಿಶಿಷ್ಟಾಯಾಂ ಶುಭತಿಥೌ ಮಮ ಉಪಾತ್ತದುರಿತಕ್ಷಯ ದ್ವಾರಾ ಶ್ರೀಪರಮೇಶ್ವರಮುದ್ದಿಶ್ಯ, ಶ್ರೀಪರಮೇಶ್ವರ ಪ್ರೀತ್ಯರ್ಥಂ ಪ್ರಾತಃ ಸಂಧ್ಯಾಮುಪಾಸಿಷ್ಯೇ ॥"
