      te: "పూర్వోక్త ఏవం గుణ విశేషణ విశిష్టాయాం శుభ తిథౌ । మమ ఉపాత్త దురితక్షయ ద్వారా శ్రీపరమేశ్వరముద్దిశ్య । శ్రీపరమేశ్వర ప్రీత్యర్థం ప్రాతః సంధ్యార్ఘ్య ప్రదానం కరిష్యే ॥\n\nఓం తత్సవితురిత్యస్య మంత్రస్య । గాధిపుత్రో విశ్వామిత్ర ఋషిః । సవితా దేవతా । గాయత్రీ ఛందః । ప్రాతః సంధ్యార్ఘ్య ప్రదానే వినియోగః ॥\n\nఓం భూర్భువః స్వః । తత్సవితుర్వరేణ్యం భర్గో దేవస్య ధీమహి । ధియో యో నః ప్రచోదయాత్ ॥",

