      mr: "पूर्वोक्त एवं गुण विशेषण विशिष्टायां शुभ तिथौ । मम उपात्त दुरितक्षय द्वारा श्रीपरमेश्वरमुद्दिश्य । श्रीपरमेश्वर प्रीत्यर्थं प्रातः सन्ध्यार्घ्य प्रदानं करिष्ये ॥\n\nॐ तत्सवितुरित्यस्य मन्त्रस्य । गाधिपुत्रो विश्वामित्र ऋषिः । सविता देवता । गायत्री छन्दः । प्रातः सन्ध्यार्घ्य प्रदाने विनियोगः ॥\n\nॐ भूर्भुवः स्वः । तत्सवितुर्वरेण्यं भर्गो देवस्य धीमहि । धियो यो नः प्रचोदयात् ॥",

