      te: "మాధ్యాహ్నిక సంధ్యాంగ ముఖ్య కాలాతిక్రమణ దోషపరిహారార్థం ప్రాయశ్చిత్తార్ఘ్య ప్రదానం కరిష్యే ॥ ప్రాతర్దేవీత్యస్య మంత్రస్య | అభితప ఋషిః | సూర్యో దేవతా | త్రిష్టుప్ ఛందః | మాధ్యాహ్నిక సంధ్యాంగ ప్రాయశ్చిత్తార్ఘ్య ప్రదానే వినియోగః ॥ ప్రాతర్దేవీమదితిం జోహవీమి మధ్యందిన ఉదితా సూర్యస్య | రాయే మిత్రా వరుణా సర్వతాతేళే తోకాయ తనయాయ శం యోః ॥ (ఇతి ప్రాయశ్చిత్తార్ఘ్యం) ॥",

