      te: "పూర్వోక్త ఏవం గుణ విశేషణ విశిష్టాయాం శుభ తిథౌ । మమ ఉపాత్త దురితక్షయ ద్వారా శ్రీపరమేశ్వరముద్దిశ్య । శ్రీపరమేశ్వర ప్రీత్యర్థం సాయం సంధ్యార్ఘ్య ప్రదానం కరిష్యే ॥\n\nఓం తత్సవితురిత్యస్య మంత్రస్య । గాధిపుత్రో విశ్వామిత్ర ఋషిః । సవితా దేవతా । గాయత్రీ ఛందః । సాయం సంధ్యార్ఘ్య ప్రదానే వినియోగః ॥\n\nఓం భూర్భువః స్వః । తత్సవితుర్వరేణ్యం భర్గో దేవస్య ధీమహి । ధియో యో నః ప్రచోదయాత్ ॥",

      sa: "पूर्वोक्त एवं गुण विशेषण विशिष्टायां शुभ तिथौ । मम उपात्त दुरितक्षय द्वारा श्रीपरमेश्वरमुद्दिश्य । श्रीपरमेश्वर प्रीत्यर्थं सायं सन्ध्यार्घ्य प्रदानं करिष्ये ॥\n\nॐ तत्सवितुरित्यस्य मन्त्रस्य । गाधिपुत्रो विश्वामित्र ऋषिः । सविता देवता । गायत्री छन्दः । सायं सन्ध्यार्घ्य प्रदाने विनियोगः ॥\n\nॐ भूर्भुवः स्वः । तत्सवितुर्वरेण्यं भर्गो देवस्य धीमहि । धियो यो नः प्रचोदयात् ॥",

      mr: "पूर्वोक्त एवं गुण विशेषण विशिष्टायां शुभ तिथौ । मम उपात्त दुरितक्षय द्वारा श्रीपरमेश्वरमुद्दिश्य । श्रीपरमेश्वर प्रीत्यर्थं सायं सन्ध्यार्घ्य प्रदानं करिष्ये ॥\n\nॐ तत्सवितुरित्यस्य मन्त्रस्य । गाधिपुत्रो विश्वामित्र ऋषिः । सविता देवता । गायत्री छन्दः । सायं सन्ध्यार्घ्य प्रदाने विनियोगः ॥\n\nॐ भूर्भुवः स्वः । तत्सवितुर्वरेण्यं भर्गो देवस्य धीमहि । धियो यो नः प्रचोदयात् ॥",

      kn: "ಪೂರ್ವೋಕ್ತ ಏವಂ ಗುಣ ವಿಶೇಷಣ ವಿಶಿಷ್ಟಾಯಾಂ ಶುಭ ತಿಥೌ । ಮಮ ಉಪಾತ್ತ ದುರಿತಕ್ಷಯ ದ್ವಾರಾ ಶ್ರೀಪರಮೇಶ್ವರಮುದ್ದಿಶ್ಯ । ಶ್ರೀಪರಮೇಶ್ವರ ಪ್ರೀತ್ಯರ್ಥಂ ಸಾಯಂ ಸಂಧ್ಯಾರ್ಘ್ಯ ಪ್ರದಾನಂ ಕರಿಷ್ಯೇ ॥\n\nಓಂ ತತ್ಸವಿತುರಿತ್ಯಸ್ಯ ಮಂತ್ರಸ್ಯ । ಗಾಧಿಪುತ್ರೋ ವಿಶ್ವಾಮಿತ್ರ ಋಷಿಃ । ಸವಿತಾ ದೇವತಾ । ಗಾಯತ್ರೀ ಛಂದಃ । ಸಾಯಂ ಸಂಧ್ಯಾರ್ಘ್ಯ ಪ್ರದಾನೇ ವಿನಿಯೋಗಃ ॥\n\nಓಂ ಭೂರ್ಭುವಃ ಸ್ವಃ । ತತ್ಸವಿತುರ್ವರೇಣ್ಯಂ ಭರ್ಗೋ ದೇವಸ್ಯ ಧೀಮಹಿ । ಧಿಯೋ ಯೋ ನಃ ಪ್ರಚೋದಯಾತ್ ॥"
