      te: "సాయం సంధ్యాంగ ముఖ్య కాలాతిక్రమణ దోషపరిహారార్థం ప్రాయశ్చిత్తార్ఘ్య ప్రదానం కరిష్యే ॥\n\nఉద్భేదభీత్యస్య మంత్రస్య । కుత్స ఋషిః । సవితా దేవతా । గాయత్రీ ఛందః । సాయం సంధ్యాంగ ప్రాయశ్చిత్తార్ఘ్య ప్రదానే వినియోగః ॥\n\nఉద్బేదభిశ్రుతా మఘం వృషభం నర్యాపసమ్ । అస్తారమేషి సూర్య ॥",

