      kn: "ಪ್ರಾತಃಕಾಲದ ತರ್ಪಣ ಮಂತ್ರಗಳನ್ನು ಪಠಿಸುತ್ತಾ ಜಲತರ್ಪಣ ಮಾಡಿ. ನಂತರ ಪುನರಾಚಮನ ಮಾಡಿ."
