        te: "మమ ఉపాత్త దురితక్షయ ద్వారా శ్రీపరమేశ్వర ముద్దిశ్య | శ్రీపరమేశ్వర ప్రీత్యర్థం ప్రాతః సంధ్యార్ఘ్య తర్పణం కరిష్యే ॥\n\nసంధ్యాం తర్పయామి |\nగాయత్రీం తర్పయామి |\nబ్రాహ్మీం తర్పయామి |\nనిమృజీం తర్పయామి ॥\n\n(పునరాచమనం కుర్యాత్)",
        sa: "मम उपात्त दुरितक्षय द्वारा श्रीपरमेश्वरमुद्दिश्य | श्रीपरमेश्वर प्रीत्यर्थं प्रातः सन्ध्यार्घ्य तर्पणं करिष्ये ॥\n\nसन्ध्यां तर्पयामि ।\nगायत्रीं तर्पयामि ।\nब्राह्मीं तर्पयामि ।\nनिमृजीं तर्पयामि ॥\n\n(पुनराचमनं कुर्यात्)",
