      mr: "देवतांचे स्मरण करून खालील श्लोक म्हणावेत.",
      kn: "ದೇವತೆಗಳನ್ನು ಸ್ಮರಿಸುತ್ತಾ ಕೆಳಗಿನ ಶ್ಲೋಕಗಳನ್ನು ಪಠಿಸಬೇಕು."
