      mr: "उत्तमे शिखरे जाते भूम्यां पर्वतमूर्धनि । ब्राह्मणेभ्योऽभ्यनुज्ञाता गच्छ देवि यथासुखम् ॥\n\nस्तुतो मया वरदा वेदमाता । प्रचोदयन्ती पवने द्विजाता । आयुः पृथिव्यां द्रविणं ब्रह्मवर्चसम् । मह्यं दत्त्वा प्रयातुं ब्रह्मलोकम् ॥",

